import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner(System.in);
        int n = sc.nextInt();
        int[] a = new int[3];
        int[] b = new int[3];
        for (int i = 0; i < 3; i++) {
            a[i] = sc.nextInt();
        }
        for (int i = 0; i < 3; i++) {
            b[i] = sc.nextInt();
        }

        int min = Math.max(0, a[0] - b[0] - b[2])
                + Math.max(0, a[1] - b[0] - b[1])
                + Math.max(0, a[2] - b[1] - b[2]);
        int max = Math.min(a[0], b[1])
                + Math.min(a[1], b[2])
                + Math.min(a[2], b[0]);

        PrintWriter pw = new PrintWriter(System.out);
        pw.println(min + " " + max);
        pw.flush();
    }

    static class FastScanner {
        private final InputStream in;
        private int current;

        FastScanner(InputStream in) throws IOException {
            this.in = in;
            this.current = in.read();
        }

        int nextInt() throws IOException {
            while (current != -1 && current <= ' ') {
                current = in.read();
            }
            int sign = 1;
            if (current == '-' || current == '+') {
                if (current == '-') {
                    sign = -1;
                }
                current = in.read();
            }
            int value = 0;
            while (current != -1 && current > ' ') {
                value = value * 10 + (current - '0');
                current = in.read();
            }
            return value * sign;
        }
    }
}
